INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b03ed87','328937da8dfced87','DrawerFrame','抽屉外壳','抽屉外壳：遮罩、头部、摘要条、工具区、正文容器；负责焦点圈定与 Escape 关闭；渲染动态区块名 DetailDrawer / <region>');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b04ed87','328937da8dfced87','DetailDrawer / Glossary','指标口径抽屉','指标口径抽屉：静态口径词条与计算示例，唯一不需要报表数据的抽屉');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b05ed87','328937da8dfced87','DetailDrawer / ManagersDrawer','支行客户经理明细抽屉','支行客户经理明细抽屉：该支行客户经理的执行指标全链路表（3.7），按任务量降序');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b06ed87','328937da8dfced87','DetailDrawer / PlansDrawer','规划明细抽屉','规划明细抽屉：某分行/支行的生效中规划列表（3.4），含来源筛选（本地过滤 plans）与四条摘要；区块名由 DrawerFrame 动态渲染');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b07ed87','328937da8dfced87','DetailDrawer / SkillsDrawer','支行技能明细抽屉','支行技能明细抽屉：该支行各技能的任务量、转化率与关联规划数（3.8），按任务量降序');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b08ed87','328937da8dfced87','DetailDrawer','明细抽屉','明细抽屉调度器：按下钻类型装配 Plans/Skills/Managers/Glossary 四种抽屉内容（逻辑 id，自身不渲染区块）');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b09ed87','328937da8dfced87','BranchWatch','需关注支行','需关注支行（3.12）：查看率或接触率低于机构基准的支行（usageLow/contactLow/bothLow 诊断标签，最多 4 条），点击下钻客户经理明细');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b0aed87','328937da8dfced87','ExecutionFunnel','执行链路漏斗','执行链路概览：任务下发→名单推荐→方案查看→洞察→电访→接触六级漏斗，附最大流失环节与人均数据（3.5）');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b0bed87','328937da8dfced87','ExecutionTable','支行执行明细表','支行执行明细表：任务/推荐/四级转化客户数与率值（3.6 服务端排序），支行名与技能数可下钻');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b0ced87','328937da8dfced87','SkillRanking','技能参与度排行','技能参与度 TOP10 横向条形图（3.11，echarts BarChart，共享 shared/echarts 动态加载）：条形为参与率（参与人数 ÷ 应执行人数），服务端按参与人数排序，悬停显示参与/应执行人数明细');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b0ded87','328937da8dfced87','TrendChart','执行走势图','所选区间逐日执行走势折线图（3.10，echarts 按需注册 + 动态加载，不进首屏 bundle）：转化率（4 条率值）/客户量（3 条数量）两种模式，悬停显示每日明细；率值为 null（分母为 0）的日期断线不画点');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b0eed87','328937da8dfced87','ExecutionView','执行视角','执行视角装配：执行链路（3.5）+ 执行走势（3.10），支行执行明细表（3.6）+ 技能参与度（3.11）/需关注支行（3.12）侧栏；五个区块各自独立请求');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b0fed87','328937da8dfced87','DateFilter','统计日期筛选','统计日期筛选：今日/近7天/近30天预设 + 自定义区间浮层（结束日期最晚为起始日期顺延一个月），已应用的区间高亮');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b10ed87','328937da8dfced87','ManagerLevelFilter','客户经理等级筛选','客户经理等级下拉筛选，选项来自筛选条件接口（等级固定存在）');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b11ed87','328937da8dfced87','OrganizationFilter','分行/支行筛选','选择分行与支行，更新报表的机构筛选范围。');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b12ed87','328937da8dfced87','SkillFilter','技能筛选','技能多选筛选：浮层内勾选，支持清空；空集表示全部技能');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b13ed87','328937da8dfced87','FiltersBar','筛选栏','筛选栏：统计日期、分行、支行、客户经理等级、技能与重置；协调日期/技能浮层互斥');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b14ed87','328937da8dfced87','PlanCoverageTable','分支行规划覆盖表','分支行规划覆盖表：分行行可展开至支行，按三种来源统计生效中规划数（3.3 树形数据），点击数量下钻明细');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b15ed87','328937da8dfced87','PlanInsights','规划洞察','规划洞察：功能待开发，当前为占位卡片（显示「开发中」，不接收数据、不渲染结论）');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b16ed87','328937da8dfced87','PlanSourceBreakdown','规划来源结构','规划来源结构（3.9）：规划数 Top 5 分行按我的关注/分行关注/行长关注的堆叠占比条');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b17ed87','328937da8dfced87','PlanningView','规划视角','规划视角装配：左侧规划覆盖表（3.3），右侧规划来源结构（3.9，Top 5）与规划洞察（占位，开发中）两张卡片');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b18ed87','328937da8dfced87','ReportHeader','报表标题与操作','页面标题、说明与操作区：导出 CSV、指标口径');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b19ed87','328937da8dfced87','Topbar','顶部导航栏','粘性顶栏：品牌、面包屑、数据更新时间、指标口径入口');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b1aed87','328937da8dfced87','ViewSwitcher','视角切换','规划/执行视角切换按钮组，附当前视角口径说明；受控组件');
INSERT INTO knowledge_component (id,page_id,component_id,name,description) VALUES ('328da30d6b1bed87','328937da8dfced87','Layout','页面主体区域','页面骨架与主体区域容器：`<main className="page">` 即 Topbar 之下的整个区域，包裹标题/筛选/指标/视角/内容/页脚；七个插槽由页面装配，样式（含响应式）在此统一导入');
