-- 所有新增主键已调用项目 CUuid.nextId() 生成。保留核心指标原数据库主键及知识关联。
SET NAMES utf8mb4;
START TRANSACTION;
SELECT id FROM knowledge_page WHERE id='328937da8dfced87' AND system_code='LQ13.03' AND project_code='zhituo' FOR UPDATE;
UPDATE knowledge_component SET component_id='MetricsStrip',name='核心指标总览' WHERE id='328937da8dfded87' AND page_id='328937da8dfced87' AND component_id IN ('kpiStrip','MetricsStrip');
UPDATE knowledge_entry SET content=REPLACE(content,'组件ID为kpiStrip','组件ID为MetricsStrip') WHERE id='328937da8e01ed87' AND system_code='LQ13.03' AND project_code='zhituo';
COMMIT;
